INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('5703b915-14a9-5d73-b253-1719445770a8', '37c845b4-486f-5bc9-8d54-50bbf6f5a908', 'text', 'Vocabulary', '{"text": "## Buying a Ticket\n\n**Ticket** — A paper or digital document showing you paid for a journey.\n_I need to buy a plane ticket._\n\n**Buy** — To get something by paying money for it.\n_Where can I buy a cheap ticket?_\n\n**Flight** — A journey made by flying in an airplane.\n_My flight to Dubai is tomorrow morning._\n\n**Online** — Using the internet on a phone or computer.\n_I always book my travel tickets online._\n\n**Price** — The amount of money you pay for something.\n_The ticket price is very high today._\n\n**Date** — The exact day and month of travel.\n_Choose your travel date on the website._\n\n**Fly** — To travel through the air in an aircraft.\n_I want to fly to Europe this summer._\n\n**Cheap** — Costing very little money; low in price.\n_This morning flight is cheap._\n\n**Seat** — The chair where you sit on an airplane.\n_I want to select a window seat._\n\n**Passport** — An official government book used to travel to other countries.\n_Keep your passport ready._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
