VALUES ('c7b522c1-5f2c-52d0-bb5d-add131564537', '37c845b4-486f-5bc9-8d54-50bbf6f5a908', 'match_pairs', 'Match the pairs', '{"instruction": "Match the word to its Russian translation", "pairs": [{"left": "Ticket", "right": "билет"}, {"left": "Buy", "right": "купить"}, {"left": "Flight", "right": "рейс"}, {"left": "Online", "right": "онлайн"}, {"left": "Price", "right": "цена"}, {"left": "Date", "right": "дата"}, {"left": "Fly", "right": "лететь"}, {"left": "Cheap", "right": "дешёвый"}, {"left": "Seat", "right": "место"}, {"left": "Passport", "right": "паспорт"}]}', 1, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
