INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b259a69a-0a57-5ef3-98e8-9cad1fa4e205', '45259568-2514-5fa5-b51c-acc5adff91d1', 'text', 'Vocabulary', '{"text": "## Packing a Suitcase\n\n**Pack** — To put clothes and items into a travel bag.\n_I pack my clothes the night before._\n\n**Suitcase** — A large, hard case with wheels used for carrying clothes.\n_My red suitcase is heavy._\n\n**Bag** — A general container made of cloth or plastic to hold things.\n_Put your jacket inside this bag._\n\n**Clothes** — Items like shirts, trousers, and jackets that you wear.\n_Pack warm clothes for the trip._\n\n**Shoes** — Coverings worn on your feet.\n_Put an extra pair of shoes in the suitcase._\n\n**Heavy** — Weighing a lot; difficult to lift.\n_Be careful, this travel bag is very heavy._\n\n**Light** — Weighing very little; easy to carry.\n_My small backpack is quite light._\n\n**Lock** — A small device used to keep your bag securely closed.\n_Put a small lock on your suitcase._\n\n**Open** — To unfasten a bag to see what is inside.\n_Please open your bag at security._\n\n**Bring** — To take someone or something with you to a place.\n_Do not forget to bring your phone charger._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
