INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('be3d5bec-2435-5ceb-8ad5-7338459b267d', 'b12800ae-7a17-52fc-a768-99cf40b4515d', 'text', 'Vocabulary', '{"text": "## Arriving at the Airport\n\n**Airport** — The large place where airplanes land and take off.\n_The airport is far from the city center._\n\n**Arrive** — To reach the destination at the end of a journey.\n_We arrive at the terminal at 2 PM._\n\n**Taxi** — A car with a driver that you pay to take you somewhere.\n_Let''s take a taxi to the airport._\n\n**Early** — Before the expected or standard time.\n_Always arrive three hours early for international flights._\n\n**Terminal** — The large building where passengers get on and off planes.\n_Which terminal does our flight leave from?_\n\n**Entrance** — The door or gate where you walk into a building.\n_Meet me at the main entrance._\n\n**Time** — What is measured in minutes and hours on a clock.\n_What time does your plane arrive?_\n\n**Find** — To locate something after looking for it.\n_I need to find the departure area._\n\n**Car** — A road vehicle with four wheels.\n_Park the car outside the terminal building._\n\n**Walk** — To move forward by putting one foot in front of the other.\n_Walk fast to reach the gate._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
