INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('ad5756ee-e795-5416-873f-a5b4761b3c74', '597467e3-fb58-5143-b993-3aa50a52d4bc', 'text', 'Vocabulary', '{"text": "## The Check-In Desk\n\n**Desk** — The counter where an airline worker helps you.\n_Go straight to the check-in desk._\n\n**Line / Queue** — A row of people waiting for their turn.\n_There is a long line at the desk._\n\n**Show** — To let someone see a document for verification.\n_Show your ticket to the agent._\n\n**Passport** — Your identification book for international border control.\n_Give your passport to the clerk._\n\n**Agent / Clerk** — The airline staff member who processes your flight.\n_The desk agent is very polite._\n\n**Drop** — To hand over your large bags so they go under the plane.\n_Drop your heavy luggage here._\n\n**Number** — A group of figures used to identify a specific flight.\n_What is your flight number?_\n\n**Wait** — To stay in one spot until it is your turn.\n_Wait in line for five minutes._\n\n**Check in** — The process of registering for your flight.\n_You can check in online or at the desk._\n\n**Ticket** — Your confirmation paper.\n_Keep your print ticket in your hand._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
