INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('12f5130c-729d-5841-bd8a-c998b7fc170e', '9d9a3114-862e-5efc-bfe4-a520988ed433', 'text', 'Vocabulary', '{"text": "## Checking in Luggage\n\n**Luggage / Baggage** — The bags and suitcases you take on a trip.\n_I have two large pieces of luggage._\n\n**Weigh** — To measure how heavy an object is on a machine scale.\n_We must weigh your suitcase._\n\n**Scale** — The machine device that shows the weight numbers.\n_Put your bag onto the digital scale._\n\n**Limit** — The maximum allowed weight for a bag.\n_The legal luggage limit is twenty kilograms._\n\n**Pay** — To give money for a service or extra fee.\n_You must pay an extra fee for heavy bags._\n\n**Heavy** — Going past the normal weight limits.\n_Your bag is too heavy for standard entry._\n\n**Tag** — A paper sticker put on your suitcase showing its destination.\n_The clerk prints a sticky luggage tag._\n\n**Belt** — The moving track that takes your suitcase away.\n_Watch your bag move on the conveyor belt._\n\n**Receipts** — Small papers showing proof of your luggage tracking.\n_Keep your luggage receipts safe._\n\n**Extra** — More than the standard or allowed amount.\n_Do you have any extra bags to check?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
