INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('bf7cd245-292f-5ebe-86ab-626b20ded42a', '8c266a42-b8e0-5aad-b794-ff2996e64720', 'text', 'Vocabulary', '{"text": "## Getting a Boarding Pass\n\n**Boarding pass** — The special card that allows you to walk onto the airplane.\n_Here is your official boarding pass._\n\n**Paper** — The physical sheet format of your pass.\n_Print the pass on white paper._\n\n**Name** — Your official identity written on the card.\n_Check the spelling of your name on the pass._\n\n**Seat** — Your assigned chair coordinates on the craft.\n_My seat number is 14A._\n\n**Gate** — The specific exit doorway where you wait to get on the plane.\n_Go directly to gate number twelve._\n\n**Time** — The exact hour passengers begin walking onto the aircraft.\n_The boarding time is 4:30 PM._\n\n**Give** — Handing an object over to someone.\n_The desk agent will give you a boarding card._\n\n**Take** — To receive or carry an object with you.\n_Take your pass and walk to security._\n\n**Class** — The type of seating section you paid for, like economy or business.\n_I am traveling in economy class._\n\n**Zone** — The specific group number used to organize boarding order.\n_My boarding pass says zone three._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
