INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('21e71b1e-8b52-5747-8c77-0fe6c62b0b72', '7169bbf2-0985-527f-be4b-8e259351eab9', 'text', 'Vocabulary', '{"text": "## Going Through Security\n\n**Security** — The airport area where officers check passengers for safety.\n_The line at airport security is moving slow._\n\n**Belt** — A moving track that takes your small items through an X-ray scanner.\n_Put your small bags on the conveyor belt._\n\n**Tray / Bin** — A plastic box used to hold your shoes, keys, and phone during checks.\n_Place your keys in the grey tray._\n\n**Shoes** — Footwear that must sometimes be removed at checkpoints.\n_Take off your heavy leather shoes, please._\n\n**Watch** — A time tracking device worn on your wrist.\n_Remove your metal watch before walking through._\n\n**Laptop** — A portable computer that must be placed alone in a bin.\n_Take your laptop out of your backpack._\n\n**Walk** — Moving your body through the safety scanner frame.\n_Walk slowly through the metal detector metal arch._\n\n**Officer** — The official safety worker checking items.\n_Listen carefully to the security officer._\n\n**Stop** — To halt your movement when asked.\n_Stop here for a secondary check, please._\n\n**Pocket** — The small cloth pouches inside your trousers or jacket.\n_Empty everything out of your pockets._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
