INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('8c1f94fd-5c6f-5186-b4fc-d5ef3006a71f', 'acebf170-decd-5447-bb44-ab94fd2643e4', 'text', 'Vocabulary', '{"text": "## Hand Luggage / Carry-on\n\n**Carry-on / Hand luggage** — The small bag you take inside the airplane cabin with you.\n_This backpack is my only carry-on._\n\n**Small** — Little in size; meeting cabin dimensions.\n_Your hand luggage must be small._\n\n**Size** — The physical dimensions of an object.\n_Check the allowed bag size on the airline app._\n\n**Backpack** — A bag you wear on your back.\n_I keep my money and documents inside my backpack._\n\n**Liquid** — Substances like water, perfume, or gel.\n_No large liquids are allowed in your carry-on._\n\n**Water** — A common clear drinking liquid.\n_Throw away your water bottle before security checks._\n\n**Fit** — To be the correct shape and size to go inside a space.\n_Does your rolling bag fit in the sizing box?_\n\n**Under** — Below a surface.\n_Place your small personal bag under the seat in front of you._\n\n**Inside** — Within the interior of a container or space.\n_Keep your passport inside your pocket._\n\n**Heavy** — Weighing too much for a cabin locker.\n_Is your carry-on backpack heavy to lift?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
