INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('451b1c0c-0b0b-51f1-a0cb-54d75cd5adeb', '49aaba93-ae35-5166-a953-d65fcdc23c45', 'text', 'Vocabulary', '{"text": "## Finding the Departure Gate\n\n**Gate** — The exact spot where passengers wait to get on a plane.\n_Our departure gate is number twenty-four._\n\n**Board / Screen** — The big digital television display showing flight information.\n_Look at the departure board for your gate._\n\n**Find** — To map your way to the correct terminal exit point.\n_Follow the overhead signs to find your gate._\n\n**Sign** — A plastic board with arrows showing directions.\n_Look at the yellow arrow sign for guidance._\n\n**Number** — The identification text for a gate doorway.\n_The gate number changed from ten to fifteen._\n\n**Walk** — Traversing the terminal pathways.\n_It is a long walk to terminal B._\n\n**Far** — A long distance away.\n_Gate forty-five is very far from this security point._\n\n**Left** — Turning toward the left-hand side.\n_Turn left after the duty-free shop._\n\n**Right** — Turning toward the right-hand side.\n_The restrooms are on the right side of the hall._\n\n**Straight** — Moving forward without turning.\n_Walk straight down this main corridor._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
