INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('3a6f8851-e1b8-5b40-9072-89628ee348e9', '6895840d-467b-5515-a2c3-e317ec014514', 'text', 'Vocabulary', '{"text": "## Waiting in the Departure Lounge\n\n**Wait** — Spending time sitting before your flight opens.\n_We must wait an hour in the departure lounge._\n\n**Lounge / Area** — The room filled with chairs near the exit gates.\n_The waiting lounge is completely full of people._\n\n**Sit** — Resting your body on an airport seat.\n_Let''s find an empty bench and sit down._\n\n**Chair / Seat** — The furniture pieces placed for travelers.\n_Are these two chairs free to use?_\n\n**Announcement** — An official voice message spoken over the airport speakers.\n_Listen to the boarding announcement._\n\n**Delay / Delayed** — When a flight is late and leaves after its scheduled time.\n_Our flight to London is delayed by two hours._\n\n**On time** — Happening exactly at the planned calendar hour.\n_Good news, our connection flight is on time._\n\n**Shop / Store** — Retail spots inside the secure zone selling snacks or gifts.\n_I want to buy a book from the airport shop._\n\n**Food** — Something you eat when hungry.\n_Let''s get some warm food before we board._\n\n**Boarding** — The process of entering the airplane plane.\n_Boarding begins in fifteen minutes._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
