INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('f25787cb-3d28-57eb-a3d4-c88630017f7a', 'ab5eeec7-a805-56f2-9d17-9ad8612ddbd6', 'text', 'Vocabulary', '{"text": "## Boarding the Airplane\n\n**Board** — To step onto an aircraft.\n_We board the plane at 5:00 PM._\n\n**Pass** — Your boarding pass document.\n_Show your pass to the flight attendant._\n\n**Queue** — A line of people waiting to board.\n_Stand in the boarding queue, please._\n\n**Walk** — To move forward into the plane cabin.\n_Walk slowly down the aisle._\n\n**Aisle** — The path between the rows of seats.\n_My seat is in the middle aisle._\n\n**Row** — A line of seats from one side of the plane to the other.\n_Look for row number twenty._\n\n**Seat** — The specific chair assigned to you.\n_Is this seat number 20A?_\n\n**Number** — The identifier for your specific seat.\n_Check the row number above your head._\n\n**Cabin** — The inside area of the airplane.\n_The cabin crew is very helpful._\n\n**Enter** — To go inside the aircraft door.\n_Enter the plane and find your row._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
