INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('b4d34a80-bcbd-5b7d-8bc1-92bb9f5cbc85', '7bd07aa8-0514-5bfa-bbe2-8e50984820af', 'text', 'Vocabulary', '{"text": "## Finding Your Seat\n\n**Find** — To locate your assigned place.\n_Help me find my seat number._\n\n**Heavy** — Your bag that needs to go in the overhead bin.\n_This bag is too heavy for the locker._\n\n**Locker / Bin** — The storage area above your seat.\n_Put your small bag in the overhead locker._\n\n**Put** — To place an item somewhere.\n_Put your jacket inside the bin._\n\n**Under** — Below your seat.\n_Place your backpack under the seat._\n\n**Window** — The glass opening by the side wall.\n_I love sitting by the window seat._\n\n**Middle** — The seat between the window and the aisle.\n_The middle seat is quite small._\n\n**Person** — Another passenger sitting near you.\n_Excuse me, can I pass the person?_\n\n**Sit** — To rest on your assigned chair.\n_Sit down and fasten your belt._\n\n**Help** — Assistance from the flight attendant.\n_Ask the attendant for help with your bag._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
