INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('855ccff0-ca13-5619-9a26-752dee51fe2c', 'fe4d0c09-7eb0-52c8-a183-f86811834454', 'text', 'Vocabulary', '{"text": "## Fastening the Seatbelt\n\n**Belt** — The safety strap across your lap.\n_Please fasten your seatbelt now._\n\n**Fasten** — To click the belt pieces together securely.\n_Fasten the belt until it clicks._\n\n**Click** — The sound made when the belt locks.\n_You will hear a click._\n\n**Tight** — Firmly held around your waist.\n_Make the belt feel tight._\n\n**Loose** — Not tight; needs adjustment.\n_The belt is too loose, adjust it._\n\n**Open** — To release the belt buckle.\n_Do not open your belt during takeoff._\n\n**Buckle** — The metal or plastic part that locks the belt.\n_Push the buckle to release it._\n\n**Safety** — Protecting yourself from movement.\n_Safety is important during turbulence._\n\n**Sign** — The glowing light showing the belt rule.\n_Look at the seatbelt sign above._\n\n**Pull** — To tug the end of the belt to tighten it.\n_Pull the strap to secure the belt._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
