INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('fb4e1d49-e6f0-5cdc-a7c6-86ff7872207c', 'f1e17ec7-16c3-5ddf-ac4a-83115d4d4714', 'text', 'Vocabulary', '{"text": "## Storing Carry-on Luggage\n\n**Store** — To put an item in a safe place.\n_Store your bag in the bin._\n\n**Locker** — The overhead storage compartment.\n_Is there space in the locker?_\n\n**Bin** — Another name for the storage locker.\n_The bin is completely full._\n\n**Above** — Higher than your head.\n_Look at the locker above your seat._\n\n**Heavy** — Weighing a lot; requires effort to lift.\n_That bag looks very heavy._\n\n**Lift** — To move an object upward.\n_I can help you lift that bag._\n\n**Full** — No more room inside the space.\n_The overhead locker is full._\n\n**Empty** — Having available space for your bag.\n_The bin is empty here._\n\n**Inside** — Within the storage area.\n_Put your laptop inside the locker._\n\n**Close** — To shut the storage locker door.\n_Close the bin door securely._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
