VALUES ('5d93dc2a-572e-5cd4-8a46-67287195584e', '447de7a2-7562-514c-8189-148e7b482b2a', 'text', 'Vocabulary', '{"text": "## Attendant Assistance\n\n**Attendant** — The staff member serving you on the plane.\n_Ask the attendant for water._\n\n**Help** — To give support or service.\n_Can you help me with this?_\n\n**Call** — To request the attendant''s attention.\n_Press the button to call for help._\n\n**Button** — The switch to signal staff.\n_Press the blue call button._\n\n**Need** — Requiring something for comfort.\n_I need a blanket, please._\n\n**Drink** — Water, juice, or coffee.\n_I would like a cold drink._\n\n**Food** — A meal served on the flight.\n_When is the food served?_\n\n**Blanket** — A warm cloth covering for sleeping.\n_Can I have a warm blanket?_\n\n**Please** — Being polite when making requests.\n_A coffee, please._\n\n**Thanks** — Expressing gratitude to the staff.\n_Thanks for your help._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
