INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a92251a4-0759-5d00-bd15-7d9dc57d0182', 'e6f19be5-7926-538a-bdff-bac0dec91b19', 'text', 'Vocabulary', '{"text": "## Takeoff and Landing\n\n**Takeoff** — The plane moving up into the sky.\n_Takeoff is in ten minutes._\n\n**Landing** — The plane coming back down to the ground.\n_Landing is very smooth today._\n\n**Sky** — The area where the plane flies.\n_The sky is very blue today._\n\n**Ground** — The surface of the earth.\n_We are on the ground now._\n\n**Wait** — To stay still during flight changes.\n_Wait until the plane stops moving._\n\n**Move** — Changing your position.\n_Do not move during takeoff._\n\n**Smooth** — Gentle and comfortable movement.\n_That was a smooth landing._\n\n**High** — At a great distance above the ground.\n_We are very high now._\n\n**Low** — Near the ground during landing.\n_The plane is flying very low._\n\n**Start** — The beginning of the flight action.\n_The pilot will start the engines._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
