INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('a1584079-a369-5976-8096-2efe3aff38f0', 'b4cd3dc6-803e-5c92-a772-3f1d69a20251', 'text', 'Vocabulary', '{"text": "## During the Flight (Comfort)\n\n**Comfortable** — Feeling relaxed and good.\n_Are you feeling comfortable?_\n\n**Rest** — To relax or sleep.\n_I want to rest during the flight._\n\n**Sleep** — To close your eyes and dream.\n_I can sleep on long flights._\n\n**Light** — The brightness in the cabin.\n_Turn off the reading light._\n\n**Noise** — Loud sounds around you.\n_The engine noise is very loud._\n\n**Quiet** — Making very little sound.\n_Please be quiet during the movie._\n\n**Movie** — A film shown on your seat screen.\n_I want to watch a movie._\n\n**Screen** — The digital display in front of you.\n_My seat screen is broken._\n\n**Cold** — Low temperature.\n_It is very cold in the cabin._\n\n**Warm** — Comfortable temperature.\n_I feel warm with my blanket._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
