INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('5f73cad1-ee37-5643-9cb3-284c6f74e961', 'e7e2a42b-85aa-5d4d-ba73-662445912e65', 'text', 'Vocabulary', '{"text": "## Airplane Meals\n\n**Meal** — Breakfast, lunch, or dinner on the plane.\n_Is the meal included?_\n\n**Eat** — To consume food.\n_I am ready to eat lunch._\n\n**Tray** — The table that folds down from the seat.\n_Lower your seat tray, please._\n\n**Table** — The surface for your food.\n_Put your tray table away now._\n\n**Chicken** — A common meat option.\n_I would like the chicken meal._\n\n**Fish** — A common seafood option.\n_Is the fish meal fresh?_\n\n**Coffee** — A hot drink.\n_One black coffee, please._\n\n**Water** — A plain clear drink.\n_A glass of water, thanks._\n\n**Taste** — The flavor of the food.\n_The food has a good taste._\n\n**Hungry** — The feeling of needing food.\n_I am very hungry now._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
