INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4587414c-7ff2-57e2-8133-3af0c8bf8b96', 'd7066b5e-86d5-5a58-b44a-63893f20e454', 'text', 'Vocabulary', '{"text": "## Using the Lavatory\n\n**Lavatory** — The bathroom on the plane.\n_Where is the lavatory, please?_\n\n**Door** — The entrance to the bathroom.\n_The lavatory door is locked._\n\n**Wait** — Standing in the aisle for your turn.\n_Wait for the light to turn green._\n\n**Free** — Available to use.\n_The lavatory is free now._\n\n**Occupied** — Being used by another person.\n_The bathroom is occupied._\n\n**Lock** — Turning the bolt to close the door.\n_Remember to lock the door._\n\n**Wash** — Cleaning your hands.\n_Wash your hands with soap._\n\n**Soap** — The liquid for cleaning.\n_There is no soap in the sink._\n\n**Sink** — The basin for water.\n_Use the water in the sink._\n\n**Return** — Going back to your seat.\n_Return to your seat quickly._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
