INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('8b5b3887-b135-5350-82c3-cd06f6c72a38', '2990e96e-f696-508e-85e7-02ca1d6b38e9', 'text', 'Vocabulary', '{"text": "## Arrival and Landing\n\n**Arrival** — Reaching your final destination.\n_Our arrival time is 8 PM._\n\n**Land** — Touching the ground safely.\n_We land in five minutes._\n\n**Bag** — Collecting your luggage.\n_I need to find my bag._\n\n**Exit** — The doorway to leave the plane.\n_Use the front exit to leave._\n\n**Wait** — Standing until the doors open.\n_Wait until the plane stops completely._\n\n**Open** — The doors unlatching.\n_The cabin doors are open now._\n\n**Thank** — Showing appreciation to the staff.\n_Thank the pilot for the flight._\n\n**Collect** — Picking up your items.\n_Collect your bags from the belt._\n\n**Home** — Your final destination.\n_I am happy to go home._\n\n**Finished** — The trip is done.\n_The flight is finished._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
