INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('218d988e-5cdc-50a4-9e87-4fd74eea5d90', '71c53d89-304b-5b14-a1c4-190c63211646', 'text', 'Vocabulary', '{"text": "## Using Public Transport\n\n**Station** — A place where trains or buses stop.\n_Where is the nearest train station?_\n\n**Bus** — A large road vehicle for many people.\n_Take the number ten bus to the center._\n\n**Train** — A series of carriages on a track.\n_The train to the city is very fast._\n\n**Ticket** — A pass allowing you to use transport.\n_You need a ticket to ride the bus._\n\n**Stop** — A specific place where a bus halts.\n_Get off at the next bus stop._\n\n**Ride** — The journey you take on public transport.\n_The ride takes twenty minutes._\n\n**Pay** — To give money for your fare.\n_You can pay the driver directly._\n\n**Price** — The cost of the journey.\n_What is the price of a ticket?_\n\n**Seat** — The place to sit on the vehicle.\n_Is this seat free to take?_\n\n**Route** — The specific path the transport follows.\n_Check the map for your bus route._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
