INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('5c3272e4-2b46-5bc6-81d0-af474f17f5dc', 'a317c262-7e33-504a-9bb7-cdef90afd235', 'text', 'Vocabulary', '{"text": "## Asking for Directions\n\n**Direction** — The way you need to travel.\n_Can you show me the direction to the park?_\n\n**Straight** — Moving ahead without turning.\n_Walk straight for two blocks._\n\n**Left** — Turning to the west or left side.\n_Turn left at the traffic lights._\n\n**Right** — Turning to the east or right side.\n_The bank is on the right._\n\n**Corner** — Where two streets meet.\n_The shop is on the corner._\n\n**Near** — A short distance away.\n_Is there a café near here?_\n\n**Far** — A long distance away.\n_The museum is too far to walk._\n\n**Street** — A road in a town or city.\n_What is the name of this street?_\n\n**Map** — A visual guide to help you find places.\n_Use this map to find your way._\n\n**Help** — Assistance with navigating.\n_Can you help me find the library?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
