INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('29572dae-9929-5168-a0e9-1f8b47f07a39', 'cfc4abc3-7b1a-571c-84ea-4c4f431de097', 'text', 'Vocabulary', '{"text": "## Visiting a Museum\n\n**Museum** — A place with history and art.\n_This museum is very interesting._\n\n**Visit** — Going to see a place.\n_I want to visit the art museum._\n\n**Ticket** — Paying to enter the building.\n_Buy your entrance ticket here._\n\n**Open** — Ready for visitors.\n_What time does the museum open?_\n\n**Time** — The hour of the day.\n_It is time to see the exhibits._\n\n**Art** — Paintings and creative works.\n_There is a lot of art here._\n\n**History** — Past events in the city.\n_Learn the history of this city._\n\n**Guide** — A person who shows you around.\n_Follow the guide to see everything._\n\n**Photo** — Taking a picture.\n_Can I take a photo here?_\n\n**Cost** — The amount to enter.\n_What is the cost of a ticket?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
