VALUES ('362871c0-c1ae-50ed-8db3-941a51994052', '20260cfb-3a41-577b-812f-ce7e2035e5e4', 'text', 'Vocabulary', '{"text": "## Eating at a Café\n\n**Café** — A small shop for drinks and light food.\n_Let''s sit in this small café._\n\n**Menu** — The list of available food and drinks.\n_Please show me the menu._\n\n**Drink** — Coffee, tea, or water.\n_I would like a cold drink._\n\n**Coffee** — A common hot drink.\n_Do you have fresh coffee?_\n\n**Water** — Essential healthy liquid.\n_A glass of water, please._\n\n**Order** — Requesting your meal.\n_Are you ready to order?_\n\n**Food** — Anything to eat.\n_The food here is delicious._\n\n**Price** — How much you must pay.\n_The price is very good._\n\n**Bill** — The document for payment.\n_Can I have the bill, please?_\n\n**Table** — The furniture where you eat.\n_Is this table free?_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
