INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('af56419c-4219-5bc1-89e9-acb8e1c7ebf0', '002eeacf-78c2-5bfa-97aa-8a6880ab6f04', 'text', 'Vocabulary', '{"text": "## The Weather\n\n**Weather** — Sun, rain, or wind.\n_What is the weather like today?_\n\n**Sunny** — Bright light from the sun.\n_It is a beautiful sunny day._\n\n**Rain** — Water falling from the sky.\n_Do not forget your umbrella for the rain._\n\n**Cold** — Low temperature.\n_It is very cold outside._\n\n**Warm** — Comfortable temperature.\n_The weather is nice and warm._\n\n**Hot** — High temperature.\n_Drink water because it is hot._\n\n**Wind** — Moving air.\n_The wind is very strong today._\n\n**Day** — A period of time.\n_Have a great day in the city._\n\n**Umbrella** — Protection from the rain.\n_I have a small umbrella._\n\n**Nice** — Generally good conditions.\n_The weather is very nice today._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
