VALUES ('aef1c11e-b162-576d-a806-bd5adb9bb9b5', 'a58157e3-bf71-52b6-9b34-ae866c40a042', 'text', 'Vocabulary', '{"text": "## Lost Items\n\n**Lost** — Cannot find your item.\n_I think my bag is lost._\n\n**Find** — Searching for it.\n_Can you help me find it?_\n\n**Phone** — Digital communication device.\n_I cannot find my phone._\n\n**Where** — Asking for location.\n_Where did you see it last?_\n\n**Bag** — The item that is gone.\n_My small bag is missing._\n\n**Help** — Asking for support.\n_Help, I lost my passport!_\n\n**Police** — Law enforcement.\n_Where is the police station?_\n\n**Office** — A place for reports.\n_Go to the lost items office._\n\n**Hope** — Wishing for success.\n_I hope to find it._\n\n**Thanks** — Gratitude for support.\n_Thanks for your help._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
