INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('65febbcb-76aa-50bf-85b6-6e806a75f475', 'ef06444f-3013-5d42-801e-5b865f73d4c8', 'text', 'Vocabulary', '{"text": "## Checking Out of the Hotel\n\n**Checkout** — The process of paying and leaving the hotel.\n_I need to do my hotel checkout at 10 AM._\n\n**Pay** — Giving money for your room stay.\n_Where can I pay for my room?_\n\n**Bill** — The document showing your total costs.\n_Can I see my final hotel bill?_\n\n**Key** — The device to open your door.\n_Here is my room key._\n\n**Leave** — To exit the building.\n_We leave the hotel at noon._\n\n**Time** — The schedule for departure.\n_What is the checkout time?_\n\n**Help** — Asking staff for assistance.\n_Can you help me with my bags?_\n\n**Taxi** — Transport to the airport.\n_Please call a taxi for the airport._\n\n**Thanks** — Showing gratitude for your stay.\n_Thanks for a great stay._\n\n**Ready** — Prepared to depart.\n_I am ready to go now._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
