INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('3106226b-fb09-50f5-a6d0-4fca73c04b7e', 'de3775ea-f687-5996-8f89-ce4cab9a4833', 'text', 'Vocabulary', '{"text": "## Getting to the Airport\n\n**Airport** — The location for your flight.\n_We must go to the airport._\n\n**Drive** — Traveling by car.\n_The drive takes thirty minutes._\n\n**Traffic** — Many cars on the road.\n_Is there a lot of traffic?_\n\n**Fast** — Moving with high speed.\n_Can we drive fast, please?_\n\n**Early** — Arriving with time to spare.\n_It is good to arrive early._\n\n**Late** — Not on time.\n_I do not want to be late._\n\n**Road** — The path for cars.\n_Which road goes to the airport?_\n\n**Stop** — A pause or end of the journey.\n_Please stop at terminal two._\n\n**Cost** — Money for the ride.\n_What is the total cost?_\n\n**Thanks** — Gratitude for the driver.\n_Thanks for the fast drive._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
