INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('4771e492-beb0-5b42-8416-662d2f7699e0', '3d3d252e-ec22-5528-a47f-beb7564aaaf6', 'text', 'Vocabulary', '{"text": "## Airline Check-in (Return)\n\n**Check-in** — Registering for your flight home.\n_Is the check-in desk open?_\n\n**Passport** — Official ID for travel.\n_Show your passport to the agent._\n\n**Ticket** — Document for your flight.\n_Here is my return ticket._\n\n**Bag** — Your luggage for the flight.\n_I have one bag to check._\n\n**Weight** — How heavy your bag is.\n_What is the bag weight today?_\n\n**Heavy** — Too much weight.\n_My bag is not too heavy._\n\n**Seat** — Your place on the plane.\n_Can I have a window seat?_\n\n**Pass** — Your boarding document.\n_Here is your boarding pass._\n\n**Gate** — Your departure area.\n_Which gate is for my flight?_\n\n**Thanks** — Being polite to staff.\n_Thanks for your help._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
