VALUES ('1971badf-4d29-55e4-adac-984b30da5ca0', '7da9bb11-bc29-5044-8c34-2fd74d1ef318', 'text', 'Vocabulary', '{"text": "## Duty-Free Shopping\n\n**Shop** — Buying items without extra tax.\n_Let''s visit the duty-free shop._\n\n**Buy** — Getting gifts.\n_I want to buy some gifts._\n\n**Gift** — A present for someone.\n_This gift is for my sister._\n\n**Item** — A single object.\n_What is the price of this item?_\n\n**Pay** — Spending money.\n_I will pay with my card._\n\n**Tax** — Government fee (none here).\n_Is there tax on this?_\n\n**Card** — Payment method.\n_Do you take this bank card?_\n\n**Bag** — Carrying your purchase.\n_I need a shopping bag._\n\n**Nice** — A pleasant item.\n_This item looks very nice._\n\n**Time** — Available minutes.\n_We have time to shop._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
