VALUES ('36d1b97a-a9db-5c9e-bf07-b211ce01f9cd', 'cb04df7c-98e0-5c43-9744-aca591d981d4', 'text', 'Vocabulary', '{"text": "## Security Check (Departure)\n\n**Security** — The safety check area.\n_Security is busy today._\n\n**Tray** — Box for your items.\n_Put your phone in the tray._\n\n**Belt** — Moving track for bags.\n_Put your bag on the belt._\n\n**Shoes** — Footwear.\n_Please take off your shoes._\n\n**Coat** — Outer garment.\n_Remove your coat, please._\n\n**Laptop** — Portable computer.\n_Put your laptop in the tray._\n\n**Walk** — Moving through the scanner.\n_Walk through the metal detector._\n\n**Wait** — Staying in line.\n_Wait for your turn here._\n\n**Empty** — Nothing inside.\n_Are your pockets empty?_\n\n**Safe** — No danger.\n_Everything is safe now._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
