VALUES ('e0c77edb-ecbd-5013-9eef-4605a3ab6627', '1ef8c340-1ded-5a12-96a0-760ca9d8c9b6', 'text', 'Vocabulary', '{"text": "## Boarding the Plane\n\n**Board** — The process of getting on.\n_Boarding will start soon._\n\n**Gate** — Your departure point.\n_Go to the boarding gate._\n\n**Pass** — Showing your ticket.\n_Have your boarding pass ready._\n\n**Walk** — Moving to the plane.\n_Walk to the aircraft now._\n\n**Row** — Your seating line.\n_Look for your seat row._\n\n**Seat** — Your assigned space.\n_My seat is near the window._\n\n**Locker** — Storing your bag.\n_Put the bag in the locker._\n\n**Sit** — Sitting down.\n_Sit in your seat, please._\n\n**Belt** — Safety strap.\n_Fasten your seatbelt, please._\n\n**Thanks** — Gratitude.\n_Thanks for the assistance._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
