INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('e9dcd235-0f82-5eaf-9707-ffbaa7d0cf15', 'd455fca3-f048-5ad9-88c0-16ca78cfb744', 'text', 'Vocabulary', '{"text": "## Landing and Exit\n\n**Land** — Reaching the ground.\n_We land in ten minutes._\n\n**Smooth** — A gentle landing.\n_That was a smooth landing._\n\n**Wait** — Staying in your seat.\n_Wait until the plane stops._\n\n**Stand** — Rising from your seat.\n_Do not stand up yet._\n\n**Door** — The exit of the plane.\n_The door is opening now._\n\n**Walk** — Moving off the plane.\n_Walk to the terminal exit._\n\n**Thanks** — Politeness.\n_Thanks for the flight._\n\n**Home** — Your return destination.\n_I am finally home!_\n\n**Bags** — Collecting luggage.\n_Go to get your bags._\n\n**Finish** — The end of the trip.\n_The journey is finished._\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
