INSERT INTO courses.steps (id, lesson_id, type, title, content, order_index, created_at, updated_at)
VALUES ('23ef0daa-b33d-52ce-84d2-d1424cd95c2f', 'b1d8c764-80b3-5408-aa44-d9b2dea6ea7a', 'text', 'Vocabulary', '{"text": "## Reflecting on the Trip\n\n**Trip** — The journey you took.\n_My trip was wonderful._\n\n**Place** — The city you visited.\n_It is a beautiful place._\n\n**Food** — What you ate.\n_The food was delicious._\n\n**People** — Those you met.\n_The people were very nice._\n\n**Photo** — Pictures taken.\n_Look at my trip photo._\n\n**Nice** — Generally good.\n_Everything was very nice._\n\n**Learn** — New knowledge.\n_I did learn many things._\n\n**Fun** — Enjoyment.\n_The trip was so much fun._\n\n**Home** — Being back.\n_It is good to be home._\n\n**Again** — Wanting to repeat.\n_I want to travel again!_\n"}', 0, NOW(), NOW())
ON CONFLICT (id) DO NOTHING;
